    18	    }
    19	
    20	    Message add(String channel, String to, String subject, String body) {
    21	        try (Connection connection = dataSource.getConnection();
    22	                PreparedStatement insert = connection.prepareStatement(
    23	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
    24	            insert.setString(1, channel);
    25	            insert.setString(2, to);
    26	            insert.setString(3, subject);
    27	            insert.setString(4, body);
    28	            try (ResultSet generated = insert.executeQuery()) {
    29	                generated.next();
    30	                return new Message(generated.getLong("id"), channel, to, subject, body);
    31	            }
    32	        } catch (SQLException failure) {
    33	            throw new IllegalStateException("could not keep the message to " + to, failure);
    34	        }
    35	    }
