    10	import javax.sql.DataSource;
    11	
    12	/** The inn's rooms. They rarely change, so they come with the database schema. */
    13	public final class Rooms {
    14	
    15	    private final DataSource dataSource;
    16	
    17	    public Rooms(DataSource dataSource) {
    18	        this.dataSource = dataSource;
    19	    }
    20	
    21	    public List<Room> all() {
    22	        try (Connection connection = dataSource.getConnection();
    23	                PreparedStatement select = connection.prepareStatement(
    24	                        "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
    25	                ResultSet rows = select.executeQuery()) {
    26	            List<Room> rooms = new ArrayList<>();
    27	            while (rows.next()) {
    28	                rooms.add(read(rows));
    29	            }
    30	            return rooms;
    31	        } catch (SQLException failure) {
    32	            throw new IllegalStateException("could not read the rooms", failure);
    33	        }
    34	    }
    35	
    36	    public Optional<Room> find(int roomNumber) {
    37	        try (Connection connection = dataSource.getConnection();
    38	                PreparedStatement select = connection.prepareStatement(
    39	                        "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
    40	            select.setInt(1, roomNumber);
    41	            try (ResultSet rows = select.executeQuery()) {
    42	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
    43	            }
