    20	class ReservationServiceTest {
    21	
    22	    private final EmptyDatabase database = new EmptyDatabase();
    23	    private final SentMessages sentMessages = new SentMessages(database.dataSource());
    24	    private final ReservationService service = new ReservationService(
    25	            new Rooms(database.dataSource()), new ReservationStore(database.dataSource()), new PriceCalculator(),
    26	            new EmailSender(sentMessages));
