    90	        List<Message> sent = sentMessages.all();
    91	        assertEquals(1, sent.size());
    92	        assertEquals("EMAIL", sent.get(0).channel());
    93	        assertEquals("ana@example.com", sent.get(0).to());
    94	        assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
    95	        assertTrue(sent.get(0).body().contains("Desconto: R$ 37,48"));
    96	        assertTrue(sent.get(0).body().contains("Total: R$ 212,42"));
    97	    }
    98	
    99	    @Test
